For the 'LearnSphere' Web-based Learning System, our team organized the ASP.NET Web Forms application using a clear folder structure (`/Admin`, `/Member`, `/Public`, `/Styles`, `/App_Data/LearnSphereDB.mdf`). We applied external CSS (`Site.css`) via a Master Page (`Site.Master`) using HTML5 semantic tags (`<header>`, `<nav>`, `<main>`, `<section>`, `<footer>`), supplemented by internal and inline styles where page-specific adjustments were needed.

Below is a core implementation snippet demonstrating HTML5 structure, ASP.NET form validation, and C# ADO.NET database connectivity (CRUD operations) for the Administrator Resource Management module (`ManageResources.aspx` and `ManageResources.aspx.cs`).

```html
<!-- ManageResources.aspx (Excerpt) -->
<section class="admin-panel" style="margin-top: 20px;">
    <h2>Manage Learning Resources</h2>
    <div class="form-group">
        <label for="txtTitle">Resource Title:</label>
        <asp:TextBox ID="txtTitle" runat="server" CssClass="form-control" />
        <asp:RequiredFieldValidator ID="rfvTitle" runat="server" 
            ControlToValidate="txtTitle" ErrorMessage="Title is required." 
            ForeColor="Red" Display="Dynamic" />
    </div>
    <div class="form-group">
        <label for="ddlCategory">Category:</label>
        <asp:DropDownList ID="ddlCategory" runat="server" CssClass="form-control">
            <asp:ListItem Text="Virtual Lab" Value="Lab" />
            <asp:ListItem Text="Self-Assessment" Value="Quiz" />
        </asp:DropDownList>
    </div>
    <div class="form-group">
        <label for="txtUrl">Resource URL:</label>
        <asp:TextBox ID="txtUrl" runat="server" TextMode="Url" CssClass="form-control" />
        <asp:RegularExpressionValidator ID="revUrl" runat="server"
            ControlToValidate="txtUrl" ErrorMessage="Enter a valid URL."
            ValidationExpression="^https?://.*" ForeColor="Red" />
    </div>
    <asp:Button ID="btnAdd" runat="server" Text="Add Resource" OnClick="btnAdd_Click" CssClass="btn-primary" />
    <asp:GridView ID="gvResources" runat="server" AutoGenerateColumns="False" DataKeyNames="ResourceID"
        OnRowDeleting="gvResources_RowDeleting" OnRowUpdating="gvResources_RowUpdating" CssClass="data-table">
    </asp:GridView>
</section>
```

```csharp
// ManageResources.aspx.cs (Excerpt)
using System;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;

public partial class Admin_ManageResources : System.Web.UI.Page
{
    string connStr = ConfigurationManager.ConnectionStrings["LearnSphereDB"].ConnectionString;

    protected void Page_Load(object sender, EventArgs e)
    {
        if (Session["Role"]?.ToString() != "Admin") Response.Redirect("~/Public/Login.aspx");
        if (!IsPostBack) BindGrid();
    }

    private void BindGrid() // DISPLAY (SELECT)
    {
        using (SqlConnection con = new SqlConnection(connStr))
        using (SqlDataAdapter sda = new SqlDataAdapter("SELECT * FROM Resources", con))
        {
            DataTable dt = new DataTable();
            sda.Fill(dt);
            gvResources.DataSource = dt;
            gvResources.DataBind();
        }
    }

    protected void btnAdd_Click(object sender, EventArgs e) // INSERT
    {
        if (!Page.IsValid) return;
        using (SqlConnection con = new SqlConnection(connStr))
        using (SqlCommand cmd = new SqlCommand("INSERT INTO Resources (Title, Category, Url) VALUES (@T, @C, @U)", con))
        {
            cmd.Parameters.AddWithValue("@T", txtTitle.Text.Trim());
            cmd.Parameters.AddWithValue("@C", ddlCategory.SelectedValue);
            cmd.Parameters.AddWithValue("@U", txtUrl.Text.Trim());
            con.Open();
            cmd.ExecuteNonQuery();
        }
        BindGrid();
    }

    protected void gvResources_RowDeleting(object sender, System.Web.UI.WebControls.GridViewDeleteEventArgs e) // DELETE
    {
        int id = Convert.ToInt32(gvResources.DataKeys[e.RowIndex].Value);
        using (SqlConnection con = new SqlConnection(connStr))
        using (SqlCommand cmd = new SqlCommand("DELETE FROM Resources WHERE ResourceID=@ID", con))
        {
            cmd.Parameters.AddWithValue("@ID", id);
            con.Open();
            cmd.ExecuteNonQuery();
        }
        BindGrid();
    }
}
```

[REQUIRES STUDENT'S OWN EVIDENCE: Complete Visual Studio solution package containing all interlinked `.aspx` pages (Registration, Login, Member Dashboard, Discussion Forum, Self-Assessment Quiz), multimedia files, `Site.css`, and the local SQL Server database `.mdf` file].
